INSERT INTO recipes (id, name, description, author_id, difficulty, portions, preparation_time, cooking_time, calorific_value, taggable_id) VALUES
(1, 'The Hamburger', 'Hamburger nach österreichischen Familienrezept', 1, 0, 4, 15, 10, 355, 5),
(2, 'Special Hamburger Sauce', 'Stark an die Big Mac Sauce angelehnte Sauce um Hamburger zu verfeinern.', 1, 0, 1, 5, 0, 812, 6),
(3, 'Apfelrosen', 'Rosen aus Äpfel und Blätterteig', 2, 2, 4, 20, 45, 121, 7),
(4, 'Lachs-Blätterteig-Schnecken', 'Apéro-Gebäck', 2, 1, 15, 15, 20, 45, 8),
(5, 'Erdbeer-Lachs-Spaghetti', 'Kombination von Fisch und Obst', 2, 1, 2, 10, 15, 1064, 9),
(6, 'Kartoffelgratin', 'Einfach und lecker', 2, 0, 2, 15, 40, 552, 10),
(7, 'Kräutersauce', 'eignet sich als Sauce für Nudeln oder Aufläufe', 2, 1, 2, 0, 0, 314, 11),
(8, 'Currywurstsauce á la Sabrina', 'Eine deutsch Spezialität', 2, 0, 2, 0, 0, 326, 12),
(9, 'Rhabarberkuchen', 'saftiger Kuchen für die Rhabarberzeit', 2, 2, 16, 0, 0, 425, 13),
(10, 'Brownies', 'Ein Brownie (auch Boston Brownie) ist ein traditionelles Gebäck der US-amerikanischen Küche.', 2, 1, 25, 20, 25, 239, 14),
(11, 'Kaiserschmarrn', 'Kaiserschmarrn, eine verfeinerte Form des Schmarrns, ist eine Zubereitung aus Palatschinkenteig und zählt zu den bekanntesten Süßspeisen der österreichischen Küche.', 1, 1, 2, 10, 30, 799, 15),
(12, 'Vanillegipferl', 'Vanillegipferl oder Vanillekipferl sind ein Österreichisches Gebäck welches oft in der Vorweihnachtszeit gebacken wird und aus einem Mürbteig aus Mehl, Butter, Zucker und gemahlenen Mandeln besteht. Das Gebäck ist so zart, dass es auf der Zunge zergeht.', 1, 2, 60, 45, 20, 55, 16),
(13, 'Louisiana Gumbo', 'Gericht mit Reis, Hähnchen und Gemüse', 2, 3, 6, 0, 0, 443, 17),
(14, 'Lachs-Sahne Gratin', 'Warum nicht mal ein Lachs gratiniert?', 2, 1, 2, 0, 0, 635, 18),
(15, 'Tomaten-Zucchini-Auflauf mit Hackfleisch', 'Wenig kalorien mit viel Geschmack', 2, 2, 2, 0, 0, 799, 19),
(16, 'Selterbäbe', '"Bäbe" ist der sächsische Begriff für einen Guglhupf.', 2, 0, 1, 0, 0, 5425, 20),
(17, 'russischer Zupfkuchen', 'Typisch deutscher Kuchen', 2, 1, 12, 0, 0, 527, 21),
(18, 'Sushi-Reis Grundrezept', 'Sushi selber machen', 2, 2, 1, 0, 0, 1018, 22),
(19, 'Feta-Hackfleisch-Auflauf', '', 2, 1, 2, 0, 0, 743, 23),
(20, 'White Chocolate Raspberry Cheesecake', 'Käsekuchen amerikanischer Art', 2, 2, 12, 0, 0, 483, 24),
(21, 'Kartoffelpuffer', 'Das liebste Gericht als Kind für den Freitag, Salat optional.', 1, 0, 2, 20, 20, 305, 25),
(22, 'Kartoffelgulasch', 'Wieder ein aufgepepptes Familienrezept', 1, 0, 4, 20, 90, 266, 26),
(23, 'Kartoffelsalat à la Mama', '', 1, 1, 4, 0, 0, 299, 27),
(24, 'Bärlauchpesto mit Rahm', 'Frisches Bärlauchpesto mit Rahm verfeinert.', 2, 0, 4, 0, 0, 349, 28),
(25, 'Mascarponecreme mit Waldbeeren', 'schnelles Dessert', 2, 1, 6, 0, 0, 396, 29),
(26, 'Avocado-Cheesecake mit Himbeeren', 'Einfacher Kuchen, der jedoch seine Zeit zum fest werden braucht.', 2, 0, 12, 0, 0, 356, 30),
(27, 'Afrikanische Gemüsesuppe', 'Etwas exotischer - aber super fein.', 2, 0, 2, 15, 30, 106, 31),
(28, 'American Pancakes', 'Die Amerikanische Form der Pfannkuchen ist im Gegensatz zum Pfannkuchen wie er in unseren Graden gemacht wird vor allem dicker und luftiger. Dies ist eine Folge des Teelöffels Backpulver. Der Anblick eines wunderschönen Pancakes-Turm macht schon mal richtig Lust und zusammen mit Ahorn-Sirup einfach grossartig.', 1, 0, 2, 0, 0, 610, 32),
(29, 'Caramellini', '', 1, 1, 40, 0, 0, 60, 33),
(30, 'Gulasch', 'Erster Anlauf', 1, 2, 4, 0, 0, 324, 34),
(31, 'Fischchnusperli', 'Ein typisches Schweizer Gericht mit einem typischen Schweizer Süsswasserfisch.', 1, 2, 1, 10, 20, 836, 35),
(32, 'Crispy Chicken mit fruchtiger Currysauce und Reis', 'Schnelles und einfaches Gericht', 2, 0, 2, 10, 20, 880, 36),
(33, 'Älpler One-Pot', 'Ein echtes Schweizer Nationalgericht einer kreativen und schnell gemachten Variante.', 1, 1, 4, 0, 0, 891, 37),
(34, 'Apo''s Freestyle Nudelgratin', '', 1, 1, 4, 0, 0, 848, 38),
(35, 'Brotrösti', 'Früher ein Rezept um altes Brot aufzubrauchen war es trotzdem ein Highlight meiner Kindheit.', 3, 0, 4, 0, 0, 202, 39),
(36, 'Apfelstudel', 'Schon Ende des 17. Jahrhunderts wurde in Österreich das erste Rezept des Apfelstrudels aufgeschrieben.', 3, 1, 10, 20, 40, 85, 40);
INSERT INTO recipe_steps (recipe_id, sort_order, text) VALUES
(1, 1, 'Semmel in Milch einweichen und danach ausdrücken.'),
(1, 2, 'Zwiebel fein hacken.'),
(1, 3, 'Hackfleisch, Zwiebel, Knoblauch, eingeweichte Semmel, Ei, Mehl, Paniermehl und die Gewürze in eine gemeinsame Schüssel geben und zu einem Teig kneten.'),
(1, 4, 'Den Fleischteig in gleichgrosse Portionen teilen, in Hamburger formen und in Paniermehl wenden. Das Fleisch nun mit wenig Öl in der heissen Pfanne anbraten.'),
(1, 5, 'Nach belieben weiterverarbeiten...'),
(2, 1, 'Alle Zutaten in einer Schüssel zusammenrühren'),
(2, 2, 'Sauce bis zum gebrauch kalt stellen.'),
(3, 1, 'Vermische das Wasser mit der Erdbeermarmelade in einer Schüssel und schneide den Apfel in sehr feine Streifen. Lege die Apfelstreifen in eine Schale mit Wasser und etwas Zitronensaft.'),
(3, 2, 'Rolle den Blätterteig aus und schneide ihn in vier gleichgrosse Streifen.'),
(3, 3, 'Bestreiche nun alle vier Streifen auf der oberen Hälfte mit dem Erdbeermarmelade-Wasser-Gemisch und streue etwas Zucker darüber.'),
(3, 4, 'Nun werden die Apfelstreifen Stück für Stück überlappend auf die Marmelade gelegt. Die Apfelspitzen sollten oben über den Blätterteig hinausragen.'),
(3, 5, 'Streue noch einmal etwas Zucker über die Äpfel und klappe den unteren Teil über die Äpfel, sodass diese in dem Blätterteig stecken.'),
(3, 6, 'Rolle den Blätterteig nun auf und stell ihn in eine Muffinform. Bei Bedarf kann man nun noch etwas Zimt darüber streuen. Anschliessend kommt alles für 45 Minuten in den Backofen bei 180°C.'),
(3, 7, 'Nach dem Backen noch mit Puderzucker bestreuen und servieren, warm oder kalt.'),
(4, 1, 'Den Blätterteig aus dem Kühlschrank nehmen und ausrollen.'),
(4, 2, 'Bestreiche den Blätterteig nun mit dem Frischkäse und streue Dill darüber.'),
(4, 3, 'Lege nun den Räucherlachs darüber und rolle den Blätterteig wieder auf.'),
(4, 4, 'Dieser Schritt kann weggelassen werden, erleichtert das Schneiden aber: Lege den Blätterteig für ca. 20 Minuten in den Tiefkühler.'),
(4, 5, 'Schneide die Rolle nun in ca. 1cm breite Rollen und lege sie auf ein mit Backpapier ausgelegtes Backblech.'),
(4, 6, 'Backe die Schnecken für ca. 20 Minuten bei 200°C.'),
(5, 1, 'Spaghetti nach Packungsanweisung kochen. Das Rezept funktioniert mit frischen oder tiefgekühlten Erdbeeren. - Die tiefgekühlten Erdbeeren sollten vor der Zubereitung leicht angetaut werden. - Frische Erdbeeren waschen und entkelchen. Erdbeeren halbieren oder vierteln.'),
(5, 2, 'Knoblauch schälen und fein hacken. Die Hälfte der Basilikumblätter grob zerpflücken und die andere Hälfte ganz lassen.'),
(5, 3, 'Das Lachsfilet trocken tupfen und in Würfel von ca. 2cm schneiden. Das Creme Fraiche in einer Pfanne erhitzen, den Knoblauch und die Lachswürfel darin anbraten.'),
(5, 4, 'Den Dill und das Basilikum nach Geschmack hinzufügen und mit Salz und Pfeffer abschmecken. Anschliessend die restlichen Basilikumblätter hinzufügen.'),
(5, 5, 'Spaghetti unter die Sauce heben und servieren.'),
(6, 1, 'Die Kartoffeln schälen und in dünne Scheiben schneiden.'),
(6, 2, 'Milch, Rahm und den fein gehackten Knoblauch vermischen und mit den Kartoffelscheiben in einen Topf geben.'),
(6, 3, 'Salz, Pfeffer und Rosmarin nach Bedarf hinzufügen.'),
(6, 4, 'Alles zusammen aufkochen und unter Rühren ca. 15-20 Minuten kochen lassen bis die Kartoffelscheiben weich sind.'),
(6, 5, 'Alles in eine Auflaufform geben, mit Käse (und Paniermehl) bestreuen und für ca. 20 Minuten bei 220°C backen lassen.'),
(7, 0, 'Creme Fraiche in einer Pfanne erhitzen und das Mehl unterrühren.'),
(7, 1, 'Bouillon unter Rühren hinzufügen und einige Minuten köcheln lassen.'),
(7, 2, 'Schnittlauch und Petersilie hinzufügen und mit Salz und Pfeffer abschmecken.'),
(8, 1, 'Alle Zutaten in einem Topf miteinander vermischen und aufkochen.'),
(9, 1, 'Alle Zutaten von Butter bis und mit gemahlene Mandeln miteinander vermischen und zu einem Teig verrühren.'),
(9, 2, 'Teig in eine Auflaufform geben, die Rhabarberstückchen darauf geben und reichlich Zucker darüber streuen.'),
(9, 3, 'Teig mit Rhabarber ca. 25 Minuten bei 180°C Heissluft backen.'),
(9, 4, 'In der Zwischenzeit für den Guss die Eiweiss steif schlagen.'),
(9, 5, 'Eigelb mit dem Zucker und Zimt vermischen.'),
(9, 6, 'Anschliessend die Zuckermasse und das Creme Fraiche vorsichtig unter das Eiweiss heben.'),
(9, 7, 'Alles auf den schon vorgebackenen Boden geben und noch einmal für ca. 30 - 35 Minuten bei 180°C Heissluft backen.'),
(10, 1, 'Butter und Schokolade unter Rühren in einer Pfanne schmelzen lassen und etwas abkühlen lassen.'),
(10, 2, 'Alle Zutaten bis und mit Salz in eine Schüssel geben und verrühren.'),
(10, 3, 'Schokoladen-Butter-Masse unterrühren.'),
(10, 4, 'Nüsse und Mehl daruntermischen. Teig in eine Form füllen und ca. 25 Minuten bei 180° C im vorgeheizten Ofen backen.'),
(11, 1, 'Für den Kaiserschmarrn zuerst in einer Schüssel Mehl, Zucker, Salz und Eigelb mit der Milch zu einem glatten, dickflüssigen Teig verrühren.'),
(11, 2, 'In einer anderen Schüssel das Eiweiss steif schlagen. Nun ist es wichtig das Eiweiss nur unterzuheben und möglichst viel Volumen zu behalten. dafür nutzt man am besten einen Teigschaber.'),
(11, 3, 'Die Butter in der Pfanne schmelen und dann denn Teig hineingiessen und 2-3min in der Pfanne bei mittlerer bis grosser Hitze Farbe annehmen lassen und dann im auf 180Grad vorgeheizten Ofen 5-6min zu Ende Backen.'),
(11, 4, 'Nun kann der Schmarrn zerrissen werden und in der Pfanne zuende braten bis er Goldgelb ist und dann mit Puderzucker bestreuen und am besten noch warm essen.'),
(12, 1, 'Mehl und Salz in eine Schüssel geben und kleine Stücke der Butter (oder Margerine) zugeben und mit kalten Händen schnell zu einer gleichmässigen Masse reiben.'),
(12, 2, 'Puderzucker, Zucker und Mandeln beigeben und zu einem Teig kneten.'),
(12, 3, 'Den Teig etwa 30min zugedeckt Kühl stellen.'),
(12, 4, 'Teig Portionsweise zwischen zwei Handflächen in etwa Stiftdicke Röllchen formen welche sich auf beiden Enden verdünnen und dann als Gipferl geformt aufs Backblech legen.'),
(12, 5, '10-15min in der Mitte des auf 200Grad vorgeheizten Ofens backen, nicht zu dunkel werden lassen.'),
(12, 6, 'Noch warm in einem Gemisch aus Puderzucker und Vanillezucker wenden oder bestreuen und abkühlen lassen.'),
(13, 1, 'Zwiebeln, Paprika, Sellerie und Knoblauch klein würfeln und zur Seite stellen. Okras in 1/2 cm dicke Schreiben schneiden.'),
(13, 2, 'Andouille in dünne Scheiben schneiden (ca. 1/2 cm dick) und in einer Pfanne mit etwas Öl 5 Minuten anbraten, anschliessend aus der Pfanne nehmen und zur Seite stellen.'),
(13, 3, 'Paprika, Pfeffer und Cayennepfeffer mischen. Das geschnitte Hähnchenfleisch damit würzen, ca. 10 Minuten anbraten. Fleisch aus der Pfanne nehmen, das Öl aber drin lassen.'),
(13, 4, 'Zwiebel, Paprika, Sellerie und Okra rund 10 Minuten anbraten, in den letzten 2 Minuten Knoblauch und den Rest der Gewürze mitdünsten. Gemüse aus der Pfanne nehmen und zur Seite stellen.'),
(13, 5, 'Nun kommt der wohl aufwändigste Teil: die Roux. Für die Roux eignet sich eine Pfanne mit schwerem Boden am besten. In der sauberen Pfanne (keine Fleisch- oder Gemüserückstände) Öl erhitzen und langsam mit einem Schneebesen Mehl einrühren. Roux rund 30 Minuten bei mittlerer Hitze unter ständigem Rühren mit einem Holzkochlöffel bräunen. Dabei darauf achten, dass nichts anbrennt (sonst wird es bitter und man muss von vorne beginnen). Das Mehl sollte gegen Ende karamellfarben sein.'),
(13, 6, 'Fleischbouillon erhitzen.'),
(13, 7, 'Nun das angebratene Gemüse mit der Roux in einem grossen Topf vermengen. Dann langsam mit einem Schöpflöffel heisse Bouillon in den Roux-Gemüsetopf einrühren. Sobald sich die Suppe gut mit dem Rest verbunden hat, den nächsten Schöpflöffel hinzugeben. Auf diese Weise etwa einen halben Liter Suppe beigeben. Den Rest der Suppe langsam unter Rühren zugiessen (mit einem Liter Suppe wird das Gericht eher flüssig, für eine dickflüssigere Konsistenz 1/8 Liter weniger Suppe verwenden).'),
(13, 8, 'Wurst und Huhn zugeben und rund 40 Minuten auf kleiner Flamme ohne Deckel köcheln lassen, dabei ab und zu umrühren. Das Gumbo dickt dabei etwas ein. Am Ende abschmecken und gegebenenfalls Nachwürzen.'),
(13, 9, 'Zum Servieren Reis in die Mitte des Tellers geben und Gumbo aufgiessen.'),
(14, 1, 'Lachs auftauen lassen. Rahm erhitzen und Speisestärke einrühren.'),
(14, 2, 'Gemüsebouillon langsam hinzufügen und aufkochen.'),
(14, 3, 'Tomatenmark, Knoblauchzehe, Pfeffer und Dill hinzugeben.'),
(14, 4, 'Lachs in eine Auflaufform geben und Sauce darübergiessen.'),
(14, 5, 'Alles in den auf 200°C vorgeheizten Ofen geben und ca. 20-30 Minuten backen. Als Beilage empfehle ich Bandnudeln und Brokkoli.'),
(15, 1, 'Tomaten, Zwiebeln und Zucchini würfeln. Reis nach Packungsanweisung zubereiten.'),
(15, 2, 'Zwiebel mit etwas Öl in eine Pfanne geben und glasig braten. Hackfleisch, Salz, Pfeffer, Cayennepfeffer und Paprikapulver hinzufügen und braten bis das Hackfleisch fast durchgebraten ist.'),
(15, 3, 'Tomaten hinzufügen und ca. 5 Minuten einkochen lassen. Dann die Zucchini hinzufügen und alles zusammen weitere 5 Minuten braten.'),
(15, 4, 'In der Zwischenzeit in einem weiteren Topf die Sauce zubereiten. Dazu Butter schmelzen und Speistärke einrühren.'),
(15, 5, 'Mit Gemüsebouillon aufgiessen und den Weisswein hinzufügen. Mit Salz und Pfeffer abschmecken. Backofen auf 200°C vorheizen.'),
(15, 6, 'Reis nun in eine Auflaufform geben, Tomaten-Zucchini-Hackfleisch-Mischung darüben geben und die Sauce darübergiessen.'),
(15, 7, 'Alles mit Käse und (optional) Paniermehl bestreuen und für ca. 15-20 Minuten backen.'),
(16, 1, 'Alle Zutaten mischen und in eine Form (Gugelhupf oder Cakeform) geben.'),
(16, 2, 'Kuchen bei 180°C ca. 60 Minuten backen.'),
(17, 1, 'Für den Teig alle Zutaten von Mehl bis und mit Backpulver mischen und zu einem Teig kneten. Teig in zwei Hälften teilen. Eine Hälfte als Boden in eine Form drücken. Die andere Hälfte zur Seite stellen.'),
(17, 2, 'Für die Füllung alle restlichen Zutaten mischen und auf den Teig geben. Restliche Hälfte des Teiges als Streusel darüber streuen. Alles bei 180°C ca. 60 Minuten backen.'),
(18, 1, 'Sushireis in einem Sieb unter fliessendem kalten Wasser abspülen bis das Wasser klar abläuft (darf nicht mehr milchig sein). Körner kurz abtropfen lassen.'),
(18, 2, 'Reis mit 300 ml Wasser aufkochen und 2 Minuten kochen lassen. Danach die Hitze reduzieren und den Reis zugedeckt bei schwacher Hitze 10 Min quellen lassen.'),
(18, 3, 'Den Deckel abnehmen, 2 Lagen Küchenpapier zwischen Topf und Deckel klemmen und den Reis weitere 15 Minuten quellen lassen.'),
(18, 4, 'In der Zwischenzeit Reisessig, Salz und Zucker kurz aufkochen und wieder etwas abkühlen lassen.'),
(18, 5, 'Reis in eine Schüssel füllen, den Würzessig unterrühren.'),
(19, 0, 'Reis nach Packungsanweisung zubereiten.'),
(19, 1, 'Alle Zutaten (ausser den Reis) braten und saure Sahne einkochen lassen.'),
(19, 2, 'Alles in eine Auflaufform schichten, etwas geriebenen Käse und Paniermehl darüber streuen und bei 200°C im Ofen backen bis der Käse geschmolzen ist.'),
(20, 1, 'Boden: Für den Boden die Butter schmelzen und die Kekse zerkrümmeln. Anschliessend Butter, 2 TL Zucker, zerkrümmelte Kekse, gemahlene Mandeln mit 2 Tropfen Mandelaroma mischen. Die Zutaten in eine vorbereitete Form (Rezept entspricht einer Form von 26cm) drücken.'),
(20, 2, 'Weisse Schokolade schmelzen.'),
(20, 3, 'Philadelphia mit Zucker und Mehl cremig rühren.'),
(20, 4, 'Schokolade unterrühren, Eier, Mandelaroma und ausgekratze Vanilleschote hinzufügen und cremig rühren. Masse zum Boden in die Form giessen.'),
(20, 5, 'Nun die Himbeerkonfitüre mit etwas Wasser mischen und anschliessend beliebig auf den Kuchen geben.'),
(20, 6, 'Im Ofen ca. 40 Minuten bei 175°C Heissluft backen bis die Oberseite leicht braun wird. Abkühlen lassen und für mehrere Stunden in den Kühlschrank stellen.'),
(20, 7, 'Am Ende die Aprikosenkonfitüre mit etwas Wasser mischen und den Rand des Kuchens damit bestreichen. Mandelblättchen andrücken.'),
(21, 1, 'Kartoffeln mit einer grossen Reibe in eine Schüssel geben wenn nötig Zellwasser abgiessen.'),
(21, 2, 'Alle weiteren Zutaten in die Schüssel dazugeben und unterrühren.'),
(21, 3, 'Portionsweise (ein Suppenlöffel) in einer Bratpfanne mit Öl goldbraun herausbacken.'),
(22, 1, '1 grosse Zwiebel klein Würfeln mit 1EL Öl in einem grossen Topf anschwitzen'),
(22, 2, 'Kartoffeln würfeln und zusammen mit dem Paprika, Kümmel und Knoblauch zu den angeschwitzen Zwiebeln in den Topf geben und mit Wasser auffüllen bis die Kartoffeln gedeckt sind.'),
(22, 3, 'Die Karotten in Scheiben schneiden, genauso die Essiggurken und zusammen mit einem Schuss Essig aus dem Gurkenglas in den Topf geben.'),
(22, 4, '60 bis 90min auf Niedriger bis Mittlerer Hitze garen.'),
(22, 5, 'Am Ende zum Verfeinern und Abschmecken kann man je nach Geschmack 6 Wienerwürstchen, etwas sauren Rahm und Sambal Olek dazugeben.'),
(23, 0, 'Die Kartoffeln mit Wasser bedeckt etwa 30-40min weich kochen.'),
(23, 1, 'Die Kartoffeln noch lauwarm schälen und in Scheiben schneiden.'),
(23, 2, 'Alle anderen Zutaten in eine Schüssel geben und zu einer Salatsauce vermischen und direk über die noch warmen Kartoffeln geben.'),
(24, 1, 'Bärlauch waschen, Pinienkerne zerhacken.'),
(24, 2, 'Alles Zutaten in den Mixer geben und mixen. Abschmecken und servieren.'),
(25, 1, 'Waldbeeren zusammen mit dem Puderzucker in einen Topf geben und aufkochen. Jenachdem wie stark man die Früchte eingekocht haben möchten köcheln lassen.'),
(25, 2, 'Rahm steifschlagen.'),
(25, 3, 'Mascarpone in eine Schüssel geben. Rahm unterrühren. Puderzucker, Vanillezucker hinzugeben.'),
(25, 4, 'Vanilleschote auskratzen und das ausgekratzte Mark zur Mascarpone-Rahm-Masse hinzufügen. Alles gut verrühren.'),
(25, 5, 'Schüssel bereitstellen. In jede Schüssel einen Butterkeks zerbröseln.'),
(25, 6, 'Mascarpone-Rahm-Creme im Wechsel mit den Waldbeeren in die Schüssel schichten.'),
(25, 7, 'Nach Wunsch dekorieren, z.B. mit Schokosplittern, und servieren.'),
(26, 1, 'Boden zubereiten: Butter schmelzen und die Kekse in einem Plastikbeutel mit einem Wallholz fein zermahlen. Die gemahlenen Kekse in eine Schüssel geben und die geschmolzene Butter darunter mischen und gut verrühren. Alles in eine vorbereitete Form geben und den Boden andrücken. Kühl stellen.'),
(26, 2, 'Nun die Cheesecake-Masse zubereiten: Avocados schälen, würfeln und zusammen mit dem Limettensaft pürieren. Creme Fraiche und Puderzucker daruntermischen.'),
(26, 3, 'Gelatine für 5 Minuten in kaltes Wasser legen. Anschliessend das Wasser gut ausdrücken und mit den 2 EL Wasser auflösen.'),
(26, 4, '2 EL der Masse in die geschmolzene Gelatine geben, gut verrühren und anschliessend zum Rest der Masser geben. Zügig alles miteinander verrühren.'),
(26, 5, 'Rahm steif schlagen und unter die Masse heben.'),
(26, 6, 'Masse auf den Boden geben und für 45 Minuten kühl stellen.'),
(26, 7, 'Himbeeren: Gelatine für 5 Minuten in kaltes Wasser legen.'),
(26, 8, 'Währenddessen die Himbeeren mit dem Puderzucker aufkochen. Gelatine gut ausdrücken und mit in den Topf geben.'),
(26, 9, 'Himbeermasse auf dem Kuchen verteilen und für ca. 3 Stunden kühl stellen.'),
(27, 1, 'Zwiebeln und Kartoffeln schälen und würfeln. Karotten in Scheiben, Chinakohl in Streifen schneiden. Alles zusammen fettfrei anrösten. Gemüsebouillon dazugiessen und für 5 Minuten köcheln.'),
(27, 2, 'Tomaten vierteln und Okras in Scheiben schneiden. Beides in die Suppe geben und weiter köcheln.'),
(27, 3, 'Erdnusscreme und Gewürze hinzufügen, weitere 5 Minuten köcheln.'),
(28, 1, 'Butter schmelzen und zusammen mit allen anderen Zutaten zu einem dicken Teig rühren.'),
(28, 2, 'Den Teig portionsweise (etwa 1 Schöpflöffel) in einer angefetteten Pfanne bei mittlerer Temperatur goldbraun backen.'),
(28, 3, 'Den Pancake drehen wenn der Teig auf der Oberseite stabile Blasen wirft.'),
(29, 0, 'Margerine in eine Schüssel geben und geschmeidig rühren.'),
(29, 1, 'Zutaten bis Mehl dazugeben und mischen'),
(29, 2, 'Mehl und Backpulver dazusieben und zu einem Teig kneten.'),
(29, 3, 'Aus dem Teig Rollen formen mit 4-5cm durchmesser und in einem Kühlschrank oder Tiefkühler fest werden lassen.'),
(29, 4, 'Den Teig in 3-4mm Dicke scheiben schneiden und auf ein Blech legen.'),
(29, 5, '6-8min bei 220 Grad im vorgeheizten Ofen hellbraun werden lassen.'),
(31, 1, 'Bier und Mehl mit dem Schwingbesen verrühren mit etwas Salz abschmecken.'),
(31, 2, 'Pro Person 160g Eglifilet würzen (Fleischgewürz) und leicht mehlen.'),
(31, 3, 'Durch den Teig ziehen und am Schüsselrand abstreifen, nur wenig Teig nehmen und schwimmend im Erdnussöl bei 180°C 2min herausbacken.'),
(31, 4, 'Auf Küchenpapier abtropfen lassen und dann mit einer halben Zitrone und Sauce Tatar servieren.'),
(32, 1, 'Reis nach Packungsanweisung zubereiten.'),
(32, 2, 'Panade vorbereiten: Dazu das Mehl und 1 TL Backpulver sowie den scharfen Paprika, Salz und Pfeffer vermischen.'),
(32, 3, 'Marinade vorbereiten Dazu das Ei, das Knoblauchpulver, Salz, edelsüssen Paprika und Cayennepfeffer miteinander verrühren.'),
(32, 4, 'Fleisch zuerst in die Marinade tauchen und anschliessend durch die Panaden-Mischung ziehen. Alles in eine Pfanne geben und braten.'),
(32, 5, 'Sauce zubereiten Rahm mit Mehl gut verrühren. Kurkuma, Currypulver, Salz und Pfeffer hinzufügen. Den Fruchtcocktail hineingeben und alles zusammen aufkochen, ca. 5 Minuten auf kleiner Stufe köcheln lassen.'),
(33, 1, 'Teigwaren und alle Zutaten bis und mit Bouillon in eine grossen Topf geben, mischen, aufkochen. Offen unter gelegentlichem Rühren bei mittlerer Hitze ca. 20 Min kochen'),
(33, 2, 'Käse daruntermischen, abschmecken, Röstzwiebeln darauf verteilen.'),
(35, 1, 'Brot in Würfel schneiden.'),
(35, 2, 'Alle anderen Zutaten zu einem Teig zusammenmischen und die Brotwürfel darin wenden.'),
(35, 3, 'Das Gemisch in einer Pfanne herausbacken bis es Goldbraun ist.'),
(36, 1, 'Blätterteig auf einem mehlbestreutem Tuch auswallen, so dünn wie möglich.'),
(36, 2, 'Haselnüsse und Paniermehl zusammen in der Pfanne rösten und Butter schmelzen.'),
(36, 3, 'Blätterteig mit Butter bepinseln und in der Mitte mit den geröstenten Nüssen belegen. (rechteckig, mit etwas rand unten und oben)'),
(36, 4, 'Die Äpfel auf die gerösteten Nüsse drauf verteilen und Rosienen drüber streuen.
