INSERT INTO recipe_hints (recipe_id, sort_order, text) VALUES
(1, 1, 'Kann wunderbar mit der Hamburger Special Sauce verfeinert werden.'),
(11, 1, 'Dazu passen verschiedene Fruchtkompotts, bei uns am beliebtesten sind eingelegte Birnen oder Zwetschgenröster. Aber auch Apfelmus passt gut dazu.'),
(20, 1, 'Mandelblättchen für den Rand vorher leicht anrösten bis sie braun sind.'),
(21, 1, 'Ein Teil der Kartoffeln mit geriebenen Zucchini / Zucchetti ersetzen.'),
(22, 1, 'Beim zweiten mal Aufkochen ist das Gericht noch besser.'),
(22, 2, '1-2TL Sambal Olek zum aufpeppen'),
(22, 3, '4 Wiener hinzufügen macht es perfekt'),
(23, 1, 'Mit einigen Oliven oder Essiggurken die Sauce aufpeppen'),
(25, 1, 'Lässt sich auch gut mit anderen Früchten, z.B. Erdbeeren, zubereiten.'),
(25, 2, 'Rahm mit Sahnesteif schlagen.'),
(26, 1, 'Himbeermasse nach dem Kochen durch ein Sieb giessen und dann auf den Kuchen geben. Dies ergibt eine glatte Oberfläche.'),
(28, 1, 'Das Eiweiss muss nicht separat geschlagen werden, aber wenn man es macht werden die Pancakes noch luftiger'),
(31, 1, 'Das würzen des Fisches macht diese Chnuschperli zu einem einmaligen Genuss.'),
(36, 1, 'Golden Delicious ist der perfekte Apfel für das Rezept, aber andere mehlige Sorten gehen auch.'),
(36, 2, 'Studelteig geht natürlich auch, ist aber ausserhalb Österreichs nicht immer einfach zu kriegen und die Schichten sind dann halt Ultradünn.'),
(36, 3, 'Rosinen kann man nach Geschmack weglassen.');
